"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5603],{87822:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"QuestTrackerController","desc":"Game Instance quest tracker (spec docs/_superpowers/specs/2026-10-15-quest-board-design.md).\\nHidden by default: a right-aligned TopbarPlus \\"Quests\\" icon (or Tab, which\\nreplaces the Roblox player list) toggles the\\nStarterGui.QuestTrackerGui panel, and holding J (keyboard) or ButtonY\\n(gamepad) shows it while held. Lists unclaimed active quests in collapsible\\nDAILY / WEEKLY sections (category glyph, task, progress; unfinished first).\\nA quest that completes while the panel is hidden adds a notice to the icon;\\nshowing the panel clears it. Never claims (claiming is in the Lobby).","realm":["Client"],"source":{"line":15,"path":"src/StarterPlayer/StarterPlayerScripts/QuestTrackerController.client.luau"}}')}}]);